using System;using System.Collections.Concurrent;using System.Collections.Generic;using WildsEngine.Discoveries.Abstractions;using WildsEngine.Discoveries.Abstractions.Consequences;using WildsEngine.Discoveries.Abstractions.Services;using WildsEngine.Discoveries.Abstractions.Truths;
namespace WildsEngine.Discoveries.Consequences { internal sealed class DiscoveryConsequenceSurface:IDiscoveryConsequenceSurface { private readonly IWildsServiceClock _clock;private readonly ConcurrentDictionary<Guid,IDiscoveryConsequenceProfile> _p=new();private readonly ConcurrentDictionary<Guid,IDiscoveryConsequenceRegistration> _r=new();public DiscoveryConsequenceSurface(IWildsServiceClock c){_clock=c;}public IDiscoveryConsequenceRegistration Register(IDiscoveryConsequenceProfile p){var identified=p.ProjectionPolicy as IIdentifiedConsequenceProjectionPolicy??throw new ArgumentException("Consequence policies must expose stable identity.");var r=new DiscoveryConsequenceRegistration(Guid.NewGuid(),p,identified.Id,_clock.GetUtcNow());if(!_p.TryAdd(p.Id,p)||!_r.TryAdd(r.Id,r))throw new InvalidOperationException("Consequence profile already registered.");return r;}public IDiscoveryConsequenceProjectionResult Project(IDiscoveryTruthCongealmentResult t,Guid id){if(!_r.TryGetValue(id,out var r)||!_p.TryGetValue(r.ProfileId,out var p))throw new KeyNotFoundException();if(t.Registration.Scope!=r.Scope)throw new InvalidOperationException("Scopes must match.");var projected=p.ProjectionPolicy.Project(t.Truths);foreach(var c in projected)foreach(var truth in c.Truths)if(!Contains(t.Truths,truth))throw new InvalidOperationException("Consequence references foreign Truth.");return new DiscoveryConsequenceProjectionResult(Guid.NewGuid(),t,r,projected,_clock.GetUtcNow());}private static bool Contains(IReadOnlyList<ITruth> list,ITruth item){foreach(var x in list)if(ReferenceEquals(x,item))return true;return false;} } }
